func (r *mutationResolver) RunPTOAccrual(ctx context.Context, input gqlmodel.RunPTOAccrualInput) (*gqlmodel.PTOAccrualRunPayload, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceWorkerPTO, permission.OpManage)
	if err != nil {
		return nil, err
	}

	info := tenantInfo(authCtx)
	asOf := int64(intValue(input.AsOf))
	if asOf <= 0 {
		asOf = timeutils.NowUnix()
	}

	if input.WorkerID == nil || *input.WorkerID == "" {
		if !r.workflowStarter.Enabled() {
			return nil, errortypes.NewValidationError(
				"workerId",
				errortypes.ErrInvalidOperation,
				"Background jobs are disabled; run accrual for a single worker instead",
			)
		}
		run, startErr := r.workflowStarter.StartWorkflow(ctx, client.StartWorkflowOptions{
			ID:        fmt.Sprintf("pto-accrual-%s-%d", info.OrgID.String(), timeutils.NowUnix()),
			TaskQueue: temporaltype.TaskQueueSystem.String(),
		}, ptojobs.PTOAccrualWorkflowName, ptojobs.PTOAccrualWorkflowInput{
			OrganizationID: info.OrgID,
			BusinessUnitID: info.BuID,
			AsOf:           asOf,
		})
		if startErr != nil {
			return nil, startErr
		}
		workflowID := run.GetID()
		return &gqlmodel.PTOAccrualRunPayload{Queued: true, WorkflowID: &workflowID}, nil
	}

	workerID, err := pulid.MustParse(*input.WorkerID)
	if err != nil {
		return nil, err
	}

	if boolValue(input.Rebuild) {
		balances, listErr := r.ptoLedgerService.GetBalances(ctx, info, workerID)
		if listErr != nil {
			return nil, listErr
		}
		for _, view := range balances {
			if _, rebuildErr := r.ptoLedgerService.RebuildBalance(ctx, &repositories.PTOBalanceKey{
				TenantInfo: info,
				WorkerID:   workerID,
				PTOType:    view.PTOType,
			}); rebuildErr != nil {
				return nil, rebuildErr
			}
		}
	}

	result, err := r.ptoLedgerService.RunAccrualForWorker(
		ctx,
		info,
		workerID,
		asOf,
		ptoledgerservice.UserActor(authCtx.UserID),
	)
	if err != nil {
		return nil, err
	}

	return &gqlmodel.PTOAccrualRunPayload{
		WorkersProcessed: result.WorkersProcessed,
		WorkersSkipped:   result.WorkersSkipped,
		EntriesPosted:    result.EntriesPosted,
		EntriesCapped:    result.EntriesCapped,
		EntriesSkipped:   result.EntriesSkipped,
	}, nil
}

