func (r *queryResolver) WorkerPTOAvailability(ctx context.Context, input gqlmodel.PTOAvailabilityInput) (*ptoledgerservice.AvailabilityResult, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceWorkerPTO, permission.OpRead)
	if err != nil {
		return nil, err
	}

	workerID, err := pulid.MustParse(input.WorkerID)
	if err != nil {
		return nil, err
	}
	excludeID, err := optionalID(input.ExcludePTOID)
	if err != nil {
		return nil, err
	}

	info := tenantInfo(authCtx)
	loc, err := r.ptoLedgerService.OrgLocation(ctx, info)
	if err != nil {
		return nil, err
	}
	countWeekends := true
	resolved, err := r.ptoLedgerService.ResolvePolicy(ctx, info, workerID, time.Now().Unix())
	if err != nil {
		return nil, err
	}
	if resolved != nil {
		countWeekends = resolved.Policy.CountWeekends
	}
	holidays, err := r.ptoLedgerService.HolidayCalendar(ctx, info)
	if err != nil {
		return nil, err
	}
	days := worker.ComputePTODays(int64(input.StartDate), int64(input.EndDate), loc, countWeekends, holidays)

	return r.ptoLedgerService.CheckAvailability(ctx, &ptoledgerservice.AvailabilityRequest{
		TenantInfo:   info,
		WorkerID:     workerID,
		PTOType:      input.PTOType,
		Days:         days,
		StartDate:    int64(input.StartDate),
		ExcludePTOID: excludeID,
	})
}

func (r *queryResolver) PreviewWorkerPTOAccrual(ctx context.Context, workerID string, asOf *int) ([]*ptoledgerservice.PlannedEntry, error) {
	authCtx, err := r.requirePermission(ctx, permission.ResourceWorkerPTO, permission.OpManage)
	if err != nil {
		return nil, err
	}

	id, err := pulid.MustParse(workerID)
	if err != nil {
		return nil, err
	}
	at := int64(intValue(asOf))
	if at <= 0 {
		at = timeutils.NowUnix()
	}

	plan, err := r.ptoLedgerService.PreviewAccrual(ctx, tenantInfo(authCtx), id, at)
	if err != nil {
		return nil, err
	}

	return plannedEntriesToPointers(plan), nil
}

